(function(){
  var root = document.querySelector('.s-room_section');
  if(!root || root.dataset.inited) return; root.dataset.inited = '1';
  var overlay = root.querySelector('.js-overlay');
  var panels = Array.prototype.slice.call(root.querySelectorAll('.js-panel'));
  var countdownEl = root.querySelector('.js-countdown');
  var timer = null;
  function currentDateTime(){
    var dEl = root.querySelector('[data-field="event_date"]');
    var tEl = root.querySelector('[data-field="event_time"]');
    var d = dEl ? dEl.textContent.trim() : '';
    var t = tEl ? tEl.textContent.trim() : '00:00';
    var dt = new Date(d + 'T' + (t.length===5 ? t+':00' : t));
    return isNaN(dt.getTime()) ? null : dt;
  }
  function tick(){
    if(!countdownEl) return;
    var target = currentDateTime();
    if(!target){ countdownEl.textContent = ''; return; }
    var diff = target.getTime() - Date.now();
    if(diff <= 0){ countdownEl.textContent = 'Hari bahagia telah tiba!'; return; }
    var s = Math.floor(diff/1000);
    var dd = Math.floor(s/86400), hh = Math.floor(s%86400/3600), mm = Math.floor(s%3600/60), ss = s%60;
    countdownEl.textContent = dd + ' hari : ' + hh + ' jam : ' + mm + ' mnt : ' + ss + ' dtk';
  }
  function open(name){
    panels.forEach(function(p){ p.hidden = p.getAttribute('data-panel') !== name; });
    overlay.hidden = false;
    if(name === 'datetime'){ tick(); if(timer) clearInterval(timer); timer = setInterval(tick, 1000); }
    var modal = root.querySelector('.s-room_section__modal');
    if(modal) modal.scrollTop = 0;
  }
  function close(){
    overlay.hidden = true;
    if(timer){ clearInterval(timer); timer = null; }
  }
  root.querySelectorAll('.js-hot').forEach(function(b){
    b.addEventListener('click', function(){ open(b.getAttribute('data-modal')); });
  });
  root.querySelectorAll('.js-close').forEach(function(b){ b.addEventListener('click', close); });
  overlay.addEventListener('click', function(e){ if(e.target === overlay) close(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && !overlay.hidden) close(); });
var roomImg=root.querySelector('.js-roomimg');var cssRoom=root.querySelector('.s-room_section__cssroom');function syncRoom(){if(!roomImg||!cssRoom)return;var s=roomImg.getAttribute('src')||roomImg.src||'';var has=!!s&&s.trim()!=='';roomImg.style.display=has?'':'none';cssRoom.hidden=has;}if(roomImg){roomImg.addEventListener('load',syncRoom);roomImg.addEventListener('error',function(){roomImg.style.display='none';if(cssRoom)cssRoom.hidden=false;});syncRoom();if('MutationObserver' in window){new MutationObserver(syncRoom).observe(roomImg,{attributes:true,attributeFilter:['src']});}}})();
